compact/posix/pi/ollama-embed/anthropic.copy:
# Keep generated configuration files out of version control.
echo .chunkhound.json >> .gitignore
echo .mcp.json >> .gitignore
# Configure ChunkHound with Ollama embeddings and Anthropic for research. Embedding and LLM providers are independent — either works without the other. Field details: https://chunkhound.ai/docs/configuration/
# You'll need: Anthropic API key
cat > .chunkhound.json <<'CHUNKHOUND_EOF'
{
  "embedding": {
    "provider": "openai",
    "model": "qwen3-embedding",
    "base_url": "http://localhost:11434/v1"
  },
  "llm": {
    "provider": "anthropic",
    "api_key": "<YOUR_ANTHROPIC_API_KEY>"
  }
}
CHUNKHOUND_EOF
# Configure Pi to connect to ChunkHound via MCP.
pi install npm:pi-mcp-adapter
if [ -f .mcp.json ]; then
cat <<'CHUNKHOUND_EOF'
.mcp.json already exists — merge this block into it manually:
{
  "mcpServers": {
    "ChunkHound": {
      "command": "chunkhound",
      "args": [
        "mcp"
      ],
      "directTools": true,
      "lifecycle": "eager",
      "requestTimeoutMs": 1200000
    }
  },
  "settings": {
    "outputGuard": false
  }
}
CHUNKHOUND_EOF
else
cat > .mcp.json <<'CHUNKHOUND_EOF'
{
  "mcpServers": {
    "ChunkHound": {
      "command": "chunkhound",
      "args": [
        "mcp"
      ],
      "directTools": true,
      "lifecycle": "eager",
      "requestTimeoutMs": 1200000
    }
  },
  "settings": {
    "outputGuard": false
  }
}
CHUNKHOUND_EOF
fi
# Build ChunkHound's search index for this project.
chunkhound index .

